def build_images(root):
    directory = Path(root)/'assets/blog'
    directory.mkdir(parents=True,exist_ok=True)
    for slug,(background,accent,label,scene) in SCENES.items():
        svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1020 540" width="1020" height="540"><title>{escape(label)} — original editorial illustration</title><defs><linearGradient id="sky" x2="1" y2="1"><stop stop-color="{background}"/><stop offset="1" stop-color="{background}" stop-opacity=".8"/></linearGradient></defs><rect width="1020" height="540" fill="url(#sky)"/><circle cx="890" cy="90" r="48" fill="{accent}" opacity=".8"/>{scene}<rect x="30" y="30" width="190" height="35" rx="17" fill="#fff" fill-opacity=".12"/><text x="48" y="53" fill="#fff8ed" font-family="sans-serif" font-size="15" letter-spacing="2">VIETNAM JOURNAL</text><text x="35" y="510" fill="#fff8ed" font-family="sans-serif" font-size="24" font-weight="bold" letter-spacing="5">{label}</text></svg>'''
        (directory/f'{slug}.svg').write_text(svg,encoding='utf-8')

if __name__=='__main__':
    build_images(Path(__file__).resolve().parents[1])
